function updatePositionArray(positionsArray, index, key, value) {
  const newArray = [...positionsArray];
  if (index >= 0 && index < newArray.length) {
    const newObject = { ...newArray[index] };

    newObject[key] = value;

    newArray[index] = newObject;

    positionsArray.setValue(newArray);
  }
}
