function replaceUndefinedValues(obj) {
    for (let key in obj) {
        if (obj[key] === undefined) {
            obj[key] = ""; 
        } else if (typeof obj[key] === 'object' && obj[key] !== null) {
            replaceUndefinedValues(obj[key]);
        }
    }
    return obj;
}


