const sortedCurrencies = fetchExpenseCatalogueData.data.data.currency.toSorted((a, b) => {
  if (a.value < b.value) {
    return -1;
  }
  if (a.value > b.value) {
    return 1;
  }
  return 0;
});

const priorityCurrencies = ["EUR","USD","RON" ];
const priorityList = sortedCurrencies.filter(currency => priorityCurrencies.includes(currency.code));
const sortedPriorityList = priorityList.toSorted((a, b) => {
  return priorityCurrencies.indexOf(a.code) - priorityCurrencies.indexOf(b.code);
});
const otherCurrencies = sortedCurrencies.filter(currency => !priorityCurrencies.includes(currency.code));

return [...sortedPriorityList, ...otherCurrencies];

